                    "description": "A parsed RFC 5322 address with optional display name.",
                    "properties": {
                      "name": {
                        "type": [
                          "string",
                          "null"
                        ],
                        "description": "Display name, when present (e.g. `Alice Example`)."
                      },
                      "address": {
                        "type": "string",
                        "description": "Bare email address (e.g. `alice@example.com`)."
                      }
                    },
